+	ping := imagick.NewMagickWand()
+	defer ping.Destroy()
+	if got := ping.GetNumberImages(); got != 0 {
+		t.Fatalf("fresh ping wand image count = %d, want 0", got)
+	}
+	requireNoError(t, "PingImageBlob", ping.PingImageBlob(blob))
+	if got := ping.GetNumberImages(); got != 1 {
+		t.Fatalf("ping image count = %d, want 1", got)
+	}
+	if got := ping.GetImageWidth(); got != 3 {
+		t.Fatalf("ping width = %d, want 3", got)
+	}
+	if got := ping.GetImageHeight(); got != 2 {
+		t.Fatalf("ping height = %d, want 2", got)
+	}
+	if got := ping.GetImageFormat(); got != "PNG" {
+		t.Fatalf("ping format = %q, want %q", got, "PNG")
+	}
+}
+
+func TestGetImagesBlobPreservesGifSequenceState(t *testing.T) {
+
+
+	initialize(t)
+
+	firstBg := imagick.NewPixelWand()
