#!/bin/bash
set -e
cd /testbed

# Install PHP if not present
if ! command -v php &>/dev/null; then
    apt-get update -qq
    apt-get install -y -qq php-cli php-xml php-mbstring php-curl php-zip unzip curl 2>&1 | tail -3
fi

# Install Composer if not present
if ! command -v composer &>/dev/null; then
    curl -sS https://getcomposer.org/installer | php -- --install-dir=/usr/local/bin --filename=composer
fi

# Block security advisories globally (PHPUnit 4 has known advisories)
composer config --global policy.advisories.block false 2>/dev/null || true

# Install project runtime dependencies only (no dev to avoid PHPUnit 4 conflict)
rm -rf vendor composer.lock
composer install --no-dev --no-interaction --ignore-platform-reqs 2>&1 | tail -3

# Install PHPUnit 7 globally if not present
if ! /root/.config/composer/vendor/bin/phpunit --version 2>/dev/null | grep -q "PHPUnit 7"; then
    composer global require phpunit/phpunit:^7.5 --no-interaction --ignore-platform-reqs 2>&1 | tail -3
fi

# Write bootstrap that loads PHPUnit 7 first, then project autoloader
cat > /testbed/.build_env/bootstrap.php <<'BOOTSTRAP'
<?php
date_default_timezone_set('America/New_York');
ini_set('session.use_cookies', 0);

// Load global PHPUnit 7 autoloader
require '/root/.config/composer/vendor/autoload.php';

// Create backward-compatible class alias for PHPUnit 4 style test classes
if (!class_exists('PHPUnit_Framework_TestCase')) {
    class_alias('PHPUnit\Framework\TestCase', 'PHPUnit_Framework_TestCase');
}

// Load project autoloader
$autoloader = require dirname(__DIR__) . '/vendor/autoload.php';
$autoloader->addPsr4('Slim\Tests\\', dirname(__DIR__) . '/tests');
BOOTSTRAP

# Run the target test
/root/.config/composer/vendor/bin/phpunit --bootstrap /testbed/.build_env/bootstrap.php --no-configuration tests/Http/StreamTest.php

